//! The four small enums of the contract, each readable from and writable to its wire name.
//!
//! Pattern: Newtype-like enums generated by one macro, so every enum has `as_str` / `parse` alike.

use serde::{Deserialize, Serialize};

macro_rules! text_enum {
    ($(#[$m:meta])* $name:ident { $($(#[$vm:meta])* $v:ident = $s:literal),+ $(,)? }) => {
        $(#[$m])*
        #[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
        pub enum $name {
            $($(#[$vm])* #[serde(rename = $s)] $v),+
        }
        impl $name {
            /// The name used in stored JSON.
            pub fn as_str(self) -> &'static str {
                match self { $(Self::$v => $s),+ }
            }
            /// The value with this stored name.
            pub fn parse(s: &str) -> Option<Self> {
                match s { $($s => Some(Self::$v),)+ _ => None }
            }
        }
    };
}

text_enum! {
    /// Where a survey is in its life (`SurveyState`).
    SurveyState {
        /// Being designed; questions can change.
        Draft = "draft",
        /// Taking answers.
        Open = "open",
        /// No more answers; results released.
        Closed = "closed",
        /// Kept for reading only.
        Archived = "archived",
    }
}

text_enum! {
    /// The promise made to respondents (`Anonymity`).
    Anonymity {
        /// The organiser sees who answered what.
        Named = "named",
        /// No identity stored; one person can answer several times.
        AnonymousOpen = "anonymousOpen",
        /// One token per invited person, not traceable by design.
        AnonymousOnce = "anonymousOnce",
        /// Anyone, no account (not built).
        Public = "public",
    }
}

text_enum! {
    /// The kind of a question (`QuestionKind`).
    QuestionKind {
        /// One choice (AS2 `oneOf`).
        SingleChoice = "singleChoice",
        /// Several choices (AS2 `anyOf`).
        MultipleChoice = "multipleChoice",
        /// Free text.
        Text = "text",
        /// A number.
        Number = "number",
        /// A full-date.
        Date = "date",
        /// One value in `[min, max]`.
        Scale = "scale",
        /// Options in order of preference.
        Ranking = "ranking",
        /// One value in `[min, max]` per option.
        OptionScores = "optionScores",
    }
}

text_enum! {
    /// How a condition compares (`ConditionOp`).
    ConditionOp {
        /// The question has an answer.
        Answered = "answered",
        /// The answer equals the value.
        Equals = "equals",
        /// The answer includes the choice.
        Includes = "includes",
        /// The number is at least the value.
        AtLeast = "atLeast",
        /// The number is at most the value.
        AtMost = "atMost",
    }
}

impl QuestionKind {
    /// Whether the question is answered from a list of choices.
    pub fn has_choices(self) -> bool {
        matches!(
            self,
            Self::SingleChoice | Self::MultipleChoice | Self::Ranking | Self::OptionScores
        )
    }
}
